import * as THREE from 'three';
import {prepareEditableWorldVisual} from './world-visual-update.js';
import {worldAssetSuffix,validWorldAsset,terrainMesh,createWorldAsset,chooseLOD,meshColliderChunks} from './world-assets.js';
import {componentDefaults,enabledComponent} from './scene-components.js';
export const worldAssetKind=p=>Object.entries(worldAssetSuffix).find(([,suffix])=>p?.endsWith(suffix))?.[0];
export function worldBufferGeometry(data){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(data.vertices.flat(),3));g.setAttribute('uv',new THREE.Float32BufferAttribute(data.uvs.flat(),2));if(data.uvs1)g.setAttribute('uv1',new THREE.Float32BufferAttribute(data.uvs1.flat(),2));if(data.colors)g.setAttribute('color',new THREE.Float32BufferAttribute(data.colors.flat(),3));g.setIndex(data.indices);if(data.normals)g.setAttribute('normal',new THREE.Float32BufferAttribute(data.normals.flat(),3));else g.computeVertexNormals();g.computeBoundingSphere();g.computeBoundingBox();return g;}
export async function loadWorldVisual(path,read,stack=[]){
 const kind=worldAssetKind(path);if(!kind||stack.includes(path)||stack.length>=16)throw Error('월드 에셋 종류·순환 참조를 확인하세요.');const data=await read(path);if(!validWorldAsset(kind,data))throw Error('월드 에셋 검증 실패: '+path);const group=new THREE.Group();group.userData.worldAsset={path,kind,dependencies:[path]};
 try{
  if(kind==='mesh'||kind==='terrain'){const d=kind==='terrain'?terrainMesh(data):data,g=worldBufferGeometry(d),m=new THREE.MeshStandardMaterial({color:kind==='terrain'?0xffffff:0x9ba9bb,roughness:.8,vertexColors:!!d.colors});group.add(new THREE.Mesh(g,m));}
  else if(kind==='foliage'){const original=data.mesh?await loadWorldVisual(data.mesh,read,[...stack,path]):await loadWorldVisualData(createWorldAsset('mesh','Plant'));group.userData.worldAsset.dependencies.push(...original.userData.worldAsset?.dependencies||[]);const meshes=[];original.traverse(o=>{if(o.isMesh)meshes.push(o);});original.updateMatrixWorld(true);const matrix=new THREE.Matrix4(),instance=new THREE.Matrix4(),q=new THREE.Quaternion(),p=new THREE.Vector3(),scale=new THREE.Vector3(),e=new THREE.Euler();for(const source of meshes){const mesh=new THREE.InstancedMesh(source.geometry,source.material,data.instances.length);for(let i=0;i<data.instances.length;i++){const v=data.instances[i];instance.compose(p.fromArray(v.position),q.setFromEuler(e.set(...v.rotation.map(THREE.MathUtils.degToRad))),scale.fromArray(v.scale));matrix.multiplyMatrices(instance,source.matrixWorld);mesh.setMatrixAt(i,matrix);}mesh.instanceMatrix.needsUpdate=true;mesh.computeBoundingSphere();mesh.userData.foliage=true;mesh.userData.foliageSourceMatrix=source.matrixWorld.clone();mesh.userData.foliageIds=data.instances.map(i=>i.id);group.add(mesh);}group.userData.foliageCount=data.instances.length;}
  else{const children=[];for(const level of data.levels){const child=await loadWorldVisual(level.asset,read,[...stack,path]);children.push(child);group.add(child);}const box=new THREE.Box3().setFromObject(group),sphere=box.isEmpty()?new THREE.Sphere(new THREE.Vector3(),1):box.getBoundingSphere(new THREE.Sphere());group.userData.worldLOD={data,children,index:-1,center:sphere.center,radius:sphere.radius};}
  group.traverse(node=>{if(node!==group&&node.userData.worldAsset)group.userData.worldAsset.dependencies.push(...node.userData.worldAsset.dependencies);});group.userData.worldAsset.dependencies=[...new Set(group.userData.worldAsset.dependencies)];group.userData.hasWorldLOD=kind==='lod';prepareEditableWorldVisual(group,kind,data);return group;
 }catch(error){disposeWorldVisual(group);throw error;}
}
async function loadWorldVisualData(data){const group=new THREE.Group();group.add(new THREE.Mesh(worldBufferGeometry(data),new THREE.MeshStandardMaterial({color:0x547a45,roughness:1})));return group;}
export function disposeWorldVisual(root){const resources=new Set();root.traverse(o=>{if(o.geometry)resources.add(o.geometry);for(const m of o.material?(Array.isArray(o.material)?o.material:[o.material]):[])resources.add(m);if(o.isInstancedMesh)resources.add(o);});for(const r of resources)r.dispose();root.clear();}
const worldCenter=new THREE.Vector3(),cameraPosition=new THREE.Vector3(),scale=new THREE.Vector3();
export function updateWorldLODs(root,camera){root.traverse(group=>{const s=group.userData.worldLOD;if(!s||!s.children.length)return;worldCenter.copy(s.center).applyMatrix4(group.matrixWorld);camera.getWorldPosition(cameraPosition);group.getWorldScale(scale);const distance=cameraPosition.distanceTo(worldCenter),radius=s.radius*Math.max(scale.x,scale.y,scale.z),screenHeight=camera.isOrthographicCamera?2*radius/(camera.top-camera.bottom)*camera.zoom:radius/(Math.max(1e-5,distance)*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))),index=chooseLOD(s.data,{distance,screenHeight,previous:s.index});if(index!==s.index){s.index=index;s.children.forEach((child,i)=>child.visible=i===index);}group.userData.lodIndex=index;});}
export async function worldCollisionGeometry(path,read,stack=[],{level}={}){
 if(level!==undefined&&(!Number.isInteger(level)||level<0))throw Error('월드 충돌 LOD 단계를 확인하세요.');
 const kind=worldAssetKind(path),data=await read(path);if(!validWorldAsset(kind,data)||stack.includes(path)||stack.length>=16)throw Error('월드 충돌 에셋 오류');if(kind==='mesh')return data;if(kind==='terrain')return terrainMesh(data);if(kind==='lod')return data.levels.length?worldCollisionGeometry(data.levels[Math.min(level??data.collisionLevel??0,data.levels.length-1)].asset,read,[...stack,path]):null;
 const base=data.mesh?await worldCollisionGeometry(data.mesh,read,[...stack,path]):createWorldAsset('mesh','Foliage'),result={version:1,name:data.name,vertices:[],indices:[],uvs:[]},matrix=new THREE.Matrix4(),q=new THREE.Quaternion(),e=new THREE.Euler(),v=new THREE.Vector3();if(!base)return null;for(const item of data.instances){matrix.compose(new THREE.Vector3(...item.position),q.setFromEuler(e.set(...item.rotation.map(THREE.MathUtils.degToRad))),new THREE.Vector3(...item.scale));const offset=result.vertices.length;for(const p of base.vertices)result.vertices.push(v.fromArray(p).applyMatrix4(matrix).toArray());result.indices.push(...base.indices.map(i=>i+offset));result.uvs.push(...base.uvs);}return result;
}
export async function prepareWorldColliders(objects,read){for(const o of objects){if(o.tileColliders)o.tileColliders=o.tileColliders.filter(c=>!c.id.startsWith('worldCollider_'));const mesh=enabledComponent(o,'MeshRenderer')?.mesh;if(!worldAssetKind(mesh))continue;const settings=enabledComponent(o,'WorldCollision');if(!settings)continue;const geometry=await worldCollisionGeometry(mesh,read),{lodMode,...collisionSettings}=settings;o.tileColliders=(o.tileColliders||[]).filter(c=>!c.id.startsWith('worldCollider_'));if(!geometry)continue;meshColliderChunks(geometry).forEach((chunk,i)=>o.tileColliders.push({id:'worldCollider_'+i,name:'World geometry',type:'MeshCollider',properties:{...componentDefaults('MeshCollider'),...collisionSettings,vertices:chunk.vertices,indices:chunk.indices,mode:'mesh'}}));}}
